class Solution {
    bool fair(long long x) {
        int odd = 0, even = 0;
        while (x) { if ((x % 10) % 2) ++odd; else ++even; x /= 10; }
        return odd == even;
    }
public:
    int closestFair(int n) {
        long long x = n;
        while (!fair(x)) {
            string s = to_string(x);
            if (s.size() % 2) {
                long long power = 1;
                for (int i = 0; i < (int)s.size(); ++i) power *= 10;
                x = power;
            } else ++x;
        }
        return (int)x;
    }
};
